mapper.select:
SELECT COUNT(*) FROM student_info WHERE deleted = 0

    AND status = #{status}


    AND grade = #{grade}


    AND major = #{major}


    AND student_type = #{studentType}

SELECT class_name AS name, COUNT(*) AS value FROM student_info WHERE deleted = 0
AND create_time between #{startTime} AND #{endTime}
GROUP BY class_name

SELECT major AS name, ROUND(COUNT(1) / #{totalStudentCount},2) AS value FROM student_info WHERE deleted = 0
AND create_time between #{startTime} AND #{endTime}
GROUP BY major

SELECT COUNT(*) FROM student_info WHERE deleted = 0

    AND grade = #{grade}


    AND class_name = #{className}


    AND create_time between #{startTime} AND #{endTime}

mapper.sql:
(SELECT h.id, '荣誉' AS recordType, honor_name AS recordTitle, s.`name` AS studentName, s.class_name AS className, h.creator, h.create_time FROM `honor_mgmt` AS h LEFT JOIN student_info AS s ON s.id = h.student_id
WHERE h.deleted = 0

    AND grade = #{grade}


    AND class_name = #{className}


    AND h.create_time between #{startTime} AND #{endTime}

)
UNION
(SELECT b.id, '行为' AS recordType, leave_reason AS recordTitle, s.`name` AS studentName, s.class_name AS className, b.creator, b.create_time FROM `behavior_mgmt` AS b LEFT JOIN student_info AS s ON s.id = b.student_id
WHERE b.deleted = 0

    AND grade = #{grade}


    AND class_name = #{className}


    AND b.create_time BETWEEN #{startTime} AND #{endTime}

)
UNION
(SELECT v.id, '行为' AS recordType, violate_reason AS recordTitle, s.`name` AS studentName, s.class_name AS className, v.creator, v.create_time FROM `violate_mgmt` AS v LEFT JOIN student_info AS s ON s.id = v.student_id
WHERE v.deleted = 0

    AND grade = #{grade}


    AND class_name = #{className}


    AND v.create_time BETWEEN #{startTime} AND #{endTime}

)
UNION
(SELECT a.id, '考评' AS recordType, a.class_name AS recordTitle, '' AS studentName, a.class_name AS className, a.creator, a.create_time FROM `assess_mgmt` AS a LEFT JOIN student_info AS s ON s.class_name = a.class_name
WHERE a.deleted = 0

    AND a.class_name = #{className}


    AND s.grede = #{grade}


    AND a.create_time BETWEEN #{startTime} AND #{endTime}

)
UNION
(SELECT m.id, '心理' AS recordType, intervene_content AS recordTitle, s.`name` AS studentName, s.class_name AS className, m.creator, m.create_time FROM `mental_mgmt` AS m LEFT JOIN student_info AS s ON s.id = m.student_id
WHERE m.deleted = 0

    AND grade = #{grade}


    AND class_name = #{className}


    AND m.create_time BETWEEN #{startTime} AND #{endTime}

)
UNION
(SELECT f.id, '资助' AS recordType, f.remark AS recordTitle, s.`name` AS studentName, s.class_name AS className, f.creator, f.create_time FROM `fund_system` AS f LEFT JOIN student_info AS s ON s.id = f.student_id
WHERE f.deleted = 0

    AND grade = #{grade}


    AND class_name = #{className}


    AND f.create_time BETWEEN #{startTime} AND #{endTime}

)
ORDER BY create_time
